function schemeById(int $id, bool $activeOnly=false): ?array {
    $sql='SELECT s.*, GROUP_CONCAT(DISTINCT c.name ORDER BY c.name SEPARATOR ", ") category_names FROM schemes s LEFT JOIN scheme_categories sc ON sc.scheme_id=s.id LEFT JOIN categories c ON c.id=sc.category_id WHERE s.id=?'.($activeOnly?" AND s.status='active'":'').' GROUP BY s.id';
    $q=db()->prepare($sql);$q->execute([$id]);return $q->fetch()?:null;
}
function profileFor(int $uid): array { $q=db()->prepare('SELECT * FROM user_profiles WHERE user_id=?');$q->execute([$uid]);return $q->fetch()?:['user_id'=>$uid]; }
function dateValue(mixed $raw): ?string { $value=trim((string)$raw);if($value==='')return null;$date=DateTime::createFromFormat('Y-m-d',$value);if(!$date||$date->format('Y-m-d')!==$value||$date>new DateTime('today'))throw new RuntimeException('Enter a valid date no later than today.');return $value; }
function schemesList(string $search='',string $category='',int $pageNo=1,bool $all=false): array {
    $limit=12;$offset=($pageNo-1)*$limit;$where=$all?'1=1':"s.status='active'";$args=[];
    if($search!==''){$where.=' AND (s.title LIKE ? OR s.summary LIKE ? OR s.description LIKE ?)';$like='%'.$search.'%';array_push($args,$like,$like,$like);}
    if($category!==''){$where.=' AND EXISTS (SELECT 1 FROM scheme_categories sx JOIN categories cx ON cx.id=sx.category_id WHERE sx.scheme_id=s.id AND cx.slug=?)';$args[]=$category;}
    $q=db()->prepare("SELECT s.*,GROUP_CONCAT(DISTINCT c.name ORDER BY c.name SEPARATOR ', ') category_names FROM schemes s LEFT JOIN scheme_categories sc ON sc.scheme_id=s.id LEFT JOIN categories c ON c.id=sc.category_id WHERE $where GROUP BY s.id ORDER BY s.updated_at DESC LIMIT $limit OFFSET $offset");$q->execute($args);return $q->fetchAll();
}

